\section{Estimation and Inference}\label{sec: estimation}
In this section, we provide three different estimators for the average long-term treat effect, corresponding to the three different identification strategies in \Cref{sec: identification} respectively. 
This involves combining two samples, so we assume that as $n \to \infty$, $n_E/n_O \to \lambda$ where $0 < \lambda < \infty$. This is a common assumption in the  data combination literature \cite[e.g., ][]{angrist1992effect,graham2016efficient}. 

\begin{theorem}[Asymptotic Distribution of Doubly Robust Estimator]\label{thm: dist-dr}
Suppose conditions in \Cref{thm: consistency} statements \ref{thm: consistency-h} and \ref{thm: consistency-q} hold and {$\min\braces{\delta_{h, n}\rho_{q, n}, \rho_{h, n}\delta_{q, n}} = o(n^{-1/2})$}. Then as $n \to \infty$, 
\begin{align*}
\sqrt{n}\prns{\hat\tau_{\dr}-\tau}  \rightsquigarrow  \mathcal{N}\prns{0, \sigma^2}, 
\end{align*}
where 
\begin{align*}
\sigma^2 
    &= \frac{1+\lambda}{\lambda}\Eb{\prns{\frac{A - \Prb{A=1\mid G=E}}{\Prb{A=1\mid G=E}}\prns{ h_0(\Sc, \Sb, A, X) - \mu(A)} }^2 \mid G = E}  \\
    &\phantom{=}+ \prns{1+\lambda} \Eb{\prns{\frac{A - \Prb{A=1\mid G=O}}{\Prb{A=1\mid G=O}}q_0\prns{\Sb, \Sa, A, X}\prns{Y - h_0(\Sc, \Sb, A, X)}}^2 \mid G = O}. \nonumber 
\end{align*}
\end{theorem}

\begin{theorem}[Asymptotic Efficiency]\label{thm: efficiency}
{Let $\mathbb{P}$ be a distribution instance such that \Cref{assump: bridge2,assump: bridge} hold with unique bridge functions and the corresponding linear operator $T$ defined above \Cref{assump: rate}  is bijective. 
Then, 
the efficiency lower bound for the average long-term treatment effect $\tau$ under \Cref{assump: CI,assump: unconfound-obs,assump: unconfound-exp,assump: ext-valid,assump: bridge},  locally evaluated at the distribution $\mathbb{P}$,  is equal to  $\sigma^2$ given in \Cref{thm: dist-dr}.}
\end{theorem}

\begin{proof}[Proof for \cref{thm: efficiency}]
{We consider a semiparametric model $\mathcal{M}_{\op{sp}}$ that places no restrictions on the data distribution except the existence of a bridge function $h_0$ in \Cref{assump: bridge}. 
Consider a regular parametric submodel indexed by a parameter $t$: $\mathcal{P}_t = \braces{p_t\prns{y, s, a, x, g}: t \in \Rl}$  
where $p_0(y, s, a, x, g)$ equals the true density $p(y, s, a, x, g)$. The associated score function is denoted as $\score(y,s, a, x, g) = \partial_t \log p_t(y, s, a, x, g) \vert_{t = 0}$. The expectation w.r.t the distribution $p_t(y, s, a, x, g)$ is denoted by $\E_t$.}


{By following the proof for Theorem 11 in \cite{kallus2021causal}, under the condition that bridge functions $h_0, q_0$ uniquely exist and the linear operator $T$ is bijective, the tangent space corresponding to $\mathcal{M}_{\op{sp}}$ is given by 
\begin{align}\label{eq: tangent}
\mathcal{S} = \bigg\{
    &\score\prns{Y, S, A, X, G} 
        = \score\prns{S_2, S_1, A, X, G} + \score\prns{Y, S_3 \mid S_2, S_1, A, X, G}: \\
    &\score\prns{S_2, S_1, A, X, G} \in  L_2\prns{S_2, S_1, A, X, G}, ~ \score\prns{Y, S_3 \mid S_2, S_1, A, X, G} \in  L_2\prns{Y, S_3 \mid S_2, S_1, A, X, G}, \nonumber \\
    &\Eb{\score\prns{S_2, S_1, A, X, G} } = 0, \Eb{\score\prns{Y, S_3 \mid S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G} = 0, \nonumber \\
    &\Eb{\prns{Y - h_0(S_3, S_2, A, X)\score\prns{Y, S_3 \mid S_2, S_1, A, X, G}}\mid S_2, S_1, A, X, G=O} \in \text{Range}(T)\bigg\}. \nonumber
\end{align}}


We now analyze the path differentiability of the counterfactual mean parameter $\mu_t\prns{a}$ under a submodel distribution with parameter value $t$. According to \Cref{thm: identification1}, we have 
\begin{align*}
 \mu_t\prns{a} = \E_t\bracks{h_t\prns{S_3, S_2, A, X} \mid A = a, G = E},
 \end{align*} 
 where $h_t\prns{S_3, S_2, A, X}$ is the corresponding outcome bridge function defined by 
\begin{align*}
\mathbb{E}_t\bracks{Y - h_t\prns{S_3, S_2, A, X} \mid S_2, S_1, A, X, G = O} = 0. 
\end{align*}

Note that we have 
\begin{align}
 \frac{\partial}{\partial t}\mu_t\prns{a}\vert_{t = 0} 
    &=  \frac{\partial}{\partial t} \mathbb{E}_t\bracks{h_t\prns{S_3, S_2, A, X} \mid A = a, G = E}\vert_{t = 0} \nonumber \\
    &= \mathbb{E}\bracks{h_0\prns{S_3, S_2, A, X}\score\prns{S_3, S_2 , X\mid A, G} \mid A = a, G = E} \label{eq: diff-1}\\
    &+ \frac{\partial}{\partial t}\Eb{h_t\prns{S_3, S_2, A, X} \mid A = a, G = E}\vert_{t = 0}.\label{eq: diff-2}
 \end{align} 

 We first analyze the term in \Cref{eq: diff-1}.
\begin{align}
 &\mathbb{E}\bracks{h_0\prns{S_3, S_2, A, X}\score\prns{S_3, S_2, X \mid A, G} \mid A = a, G = E}  \label{eq: efficiency-term1} \\
    =& \mathbb{E}\bracks{\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}}\score\prns{S_3, S_2, X\mid A, G} \mid A = a, G = E} \nonumber  \\
    =& \mathbb{E}\bracks{\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}}\score\prns{S_3, S_2, A, X, G} \mid A = a, G = E} \nonumber \\
    =& \mathbb{E}\bracks{\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}}\score\prns{Y, S_3, S_2, S_1, A, X, G} \mid A = a, G = E} \nonumber \\
    =& \mathbb{E}\bracks{\frac{\indic{A = a, G = E}}{\Prb{A= a, G = E}}\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}}\score\prns{Y, S_3, S_2, S_1, A, X, G}} \nonumber
 \end{align}
 where the second equation holds because 
 \begin{align*}
 &\Eb{\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}}\score\prns{A, G} \mid A = a, G = E} \\
 =&   \Eb{\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}} \mid A = a, G = E} \score\prns{A=a, G=E} = 0,
 \end{align*}
 and the third equation holds because 
 \begin{align*}
 &\Eb{\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}}\score\prns{Y, S_1 \mid S_3, S_2, A, X, G} \mid A = a, G = E} \\
 =&  \Eb{\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}}\Eb{\score\prns{Y, S_1 \mid S_3, S_2, A, X, G} \mid S_3, S_2, A, X, G} \mid A = a, G = E} = 0.
 \end{align*}


Next we analyze the term in \Cref{eq: diff-2}.
\begin{align*}
 &\frac{\partial}{\partial t}\Eb{h_t\prns{S_3, S_2, A, X} \mid A = a, G = E}\vert_{t = 0} \\
    &= \frac{\partial}{\partial t}\Eb{\frac{p\prns{S_3, S_2, X \mid A, G = E}}{p\prns{S_3, S_2, X \mid A, G = O}}  h_t\prns{S_3, S_2, A, X} \mid A = a, G = O}\vert_{t = 0} \\
    &= \frac{\partial}{\partial t}\Eb{q_0\prns{S_2, S_1, A, X}h_t\prns{S_3, S_2, A, X} \mid A = a, G = O}\vert_{t = 0} \\
    &= \Eb{q_0\prns{S_2, S_1, A, X}\frac{\partial}{\partial t} \Eb{h_t\prns{S_3, S_2, A, X} \mid S_2, S_1, A, X, G = O}\vert_{t = 0} \mid A = a, G = O},
 \end{align*}
 where the second equation holds because of \Cref{eq: bridge2-obs-1}. 

 Furthermore, by taking the derivative of the left hand side w.r.t $t$ at $t = 0$, we have 
\begin{align}\label{eq: path-diff-1}
&\frac{\partial}{\partial t}\Eb{h_t\prns{S_3, S_2, A, X} \mid S_2, S_1, A, X, G = O}\vert_{t = 0} \nonumber \\
=& \Eb{\prns{Y - h_0\prns{S_3, S_2, A, X}}\score\prns{Y, S_3 \mid S_2, S_1, A,X,  G} \mid S_2, S_1, A,X, G = O} = 0.
\end{align} 
It follows that 
 \begin{align}
 &\frac{\partial}{\partial t}\Eb{h_t\prns{S_3, S_2, A, X} \mid A = a, G = E}\vert_{t = 0} \label{eq: efficiency-term2} \\
    &= \Eb{q_0\prns{S_2, S_1, A, X}{\prns{Y - h_0\prns{S_3, S_2, A, X}}}\score\prns{Y, S_3 \mid S_2, S_1, A, X, G}\mid A = a, G = O} \nonumber \\
    &= \Eb{q_0\prns{S_2, S_1, A, X}{\prns{Y - h_0\prns{S_3, S_2, A, X}}}\score\prns{Y, S_3, S_2, S_1, A, X, G}\mid A = a, G = O} \nonumber \\
    &= \Eb{\frac{\indic{A = a, G = O}}{\Prb{A = a, G = O}}q_0\prns{S_2, S_1, A, X}{\prns{Y - h_0\prns{S_3, S_2, A, X}}}\score\prns{Y, S_3, S_2, S_1, A, X, G}}, \nonumber 
 \end{align}
 where the second equation holds because 
  \begin{align*}
 &\Eb{q_0\prns{S_2, S_1, A, X}{\prns{Y - h_0\prns{S_3, S_2, A, X}}}\score\prns{S_2, S_1, A, X, G}\mid A = a, G = O} \\
 =& \E\big[q_0\prns{S_2, S_1, A, X}\Eb{Y - h_0\prns{S_3, S_2, A, X} \mid S_2, S_1, A, X, G = O} \\
 &\qquad\qquad\qquad\qquad\qquad\qquad  \times \score\prns{S_2, S_1, A,X,  G = O}\mid A = a, G = O\big] = 0.
 \end{align*}

 Combining \Cref{eq: efficiency-term1,eq: efficiency-term2}, we have 
  \begin{align*}
   \frac{\partial}{\partial t}\mu_t\prns{a}\vert_{t = 0} = \Eb{\psi_a\prns{Y, S_3, S_2, S_1, A, X, G}\score\prns{Y, S_3, S_2, S_1, A, X, G}},
  \end{align*} 
where 
\begin{align*}
\psi_a\prns{Y, S_3, S_2, S_1, A, X, G} 
    &= \frac{\indic{A = a, G = E}}{\Prb{A = a, G = E}}\prns{h_0\prns{S_3, S_2, A, X} - \mu\prns{a}} \nonumber \\
    & + \frac{\indic{A = a, G = O}}{\Prb{A = a, G = O}}q_0\prns{S_2, S_1, A, X}\prns{Y - h_0\prns{S_3, S_2, A, X}}.  
\end{align*}
Therefore, 
\begin{align*}
\frac{\partial}{\partial t}\tau_t\vert_{t = 0}  &= \frac{\partial}{\partial t}\mu_t\prns{1}\vert_{t = 0} - \frac{\partial}{\partial t}\mu_t\prns{0}\vert_{t = 0} \\
  &= \Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G}\score\prns{Y, S_3, S_2, S_1, A, X, G}},
\end{align*}
where 
\begin{align*}
&\psi\prns{Y, S_3, S_2, S_1, A, X, G}  \\
    =& \psi_1\prns{Y, S_3, S_2, S_1, A, X, G} - \psi_0\prns{Y, S_3, S_2, S_1, A, X, G} - \tau \\
    =& \frac{\indic{G = E}}{\Prb{G = E}}\frac{A - \Prb{A = 1 \mid G = E}}{\Prb{A = 1 \mid G = E}}\prns{h_0\prns{S_3, S_2, A, X} - \mu(A)} \\
    +& \frac{\indic{G = O}}{\Prb{G = O}}\frac{A - \Prb{A=1\mid G=O}}{\Prb{A=1\mid G=O}}q_0\prns{S_2, S_1, A, X}\prns{Y - h_0\prns{S_3, S_2, A, X}} - \tau.
\end{align*}

{
We can easily decompose  $\psi\prns{Y, S_3, S_2, S_1, A, X, G}$ into two terms:
\begin{align*}
\psi\prns{Y, S_3, S_2, S_1, A, X, G} 
&= \Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G} - \tau \\
&+ \psi\prns{Y, S_3, S_2, S_1, A, X, G} - \Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G},
\end{align*}
where 
\begin{align*}
&\Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G} - \tau \in L_2(S_2, S_1, A, X, G) \\
&\Eb{\Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G} - \tau} = 0 \\
& \psi\prns{Y, S_3, S_2, S_1, A, X, G} - \Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G} \in L_2(Y, S_3 \mid S_2, S_1, A, X, G) \\
& \Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} - \Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G} = 0.
\end{align*}
Moreover, since $T$ is surjective, its range space $\text{Range}(T)$ is the whole $L_2(S_2, S_1, A, X)$ space so we automatically have 
\begin{align*}
 &\mathbb{E}\big[\prns{\psi\prns{Y, S_3, S_2, S_1, A, X, G} - \Eb{\psi\prns{Y, S_3, S_2, S_1, A, X, G} \mid S_2, S_1, A, X, G}}\\
 &\qquad\qquad\qquad\qquad \times \prns{Y - h_0(S_3, S_2, A, X)} \mid S_2, S_1, A, X, G = O\big] \in \text{Range}(T). 
 \end{align*} 
 This means that $\psi\prns{Y, S_3, S_2, S_1, A, X, G}$ belongs to the tangent space $\mathcal{S}$. 
Thus $\psi\prns{Y, S_3, S_2, S_1, A, X, G}$ is the efficient influence function for $\tau$, and its variance, which is equal to $\sigma^2$ in \Cref{thm: efficiency}, is the semiparametric efficiency lower bound for $\tau$ relative to the tangent space $\mathcal{S}$ in \Cref{eq: tangent}.
} 
\end{proof}

statements.statement:
Fix \(P\in\mathfrak P_{\mathcal D}^{\mathrm{obs}}\).  The full-catalogue pilot \(\mathcal P_m\) is independent of the main study.  Within the pilot and within the main study, the experimental and observational source samples are mutually independent and consist of independent and identically distributed observations from their respective source-conditional laws.  For each \(d\in\mathcal D\), write \(H_d=(S_{3d},S_{2d},A,X)\) and \(L_d=(S_{2d},S_{1d},A,X)\).  Suppose the following fixed-dimensional conditions hold.

For each \((d,a)\), there are known, bounded, finite-dimensional bridge bases \(b^h_{d,a}(H_d)\) and \(b^q_{d,a}(L_d)\), and known bounded test bases \(z^h_{d,a}(L_d)\) and \(z^q_{d,a}(H_d)\), whose dimensions do not depend on \(m\) or \(B\), such that
\[
 h_d(H_d)=b^h_{d,a}(H_d)^\top\beta_{d,a},
 \qquad
 q_d(L_d)=b^q_{d,a}(L_d)^\top\gamma_{d,a}
 \quad\text{on }\{A=a\}.                                    \tag{1}
\]
The square population moment matrices
\[
 M^h_{d,a}=E_P\{z^h_{d,a}(L_d)b^h_{d,a}(H_d)^\top\mid A=a,G=O\},
 \qquad
 M^q_{d,a}=E_P\{z^q_{d,a}(H_d)b^q_{d,a}(L_d)^\top\mid A=a,G=O\} \tag{2}
\]
have smallest singular values bounded below by a constant \(c_0>0\), uniformly over the finite set of \((d,a)\); the corresponding basis Gram matrices have eigenvalues in \([c_0,c_0^{-1}]\).  The exact moment equations are
\[
 M^h_{d,a}\beta_{d,a}
 =E_P\{z^h_{d,a}(L_d)Y\mid A=a,G=O\},
 \qquad
 M^q_{d,a}\gamma_{d,a}
 =E_P\{z^q_{d,a}(H_d)\mid A=a,G=E\}.                         \tag{3}
\]
There are \(\delta>0\) and \(C_0<\infty\) such that all four bases are bounded by \(C_0\), \(E_P(|Y|^{4+\delta}\mid G=O)\le C_0\), and every source and source-arm probability is at least \(c_0\).  Pilot source-arm sizes, main-study source-arm sizes, and every training and evaluation fold size are proportional to \(m\) or \(B\), as appropriate, with fixed \(L\).

On each training sample, form the empirical conditional analogues of (2)--(3) and set
\[
 \widehat\beta_{d,a}=\widehat M_{d,a}^{h,-1}\widehat g^h_{d,a},
 \qquad
 \widehat\gamma_{d,a}=\widehat M_{d,a}^{q,-1}\widehat g^q_{d,a}, \tag{4}
\]
with value zero when a displayed empirical matrix is singular.  Use the resulting fold-external linear bridge fits in the pilot and main study, and use the empirical plug-in source-score second moments specified in Definitions~\(\mathrm{def{:}pilot\text{-}selector}\) and \(\mathrm{def{:}selected\text{-}wald\text{-}variance}\).

Then, uniformly over the finite catalogue and the fixed folds,
\[
 \|\widehat h_{d,B}^{(-\ell)}-h_d\|_{2,B}^{\circ}
 +\|T_d(\widehat h_{d,B}^{(-\ell)}-h_d)\|_{2,O,q,d}
 =O_P(B^{-1/2}),                                               \tag{5}
\]
\[
 \|\widehat q_{d,B}^{(-\ell)}-q_d\|_{2,O,q,d}
 +\|T_d^\star(\widehat q_{d,B}^{(-\ell)}-q_d)\|_{2,B}^{\circ}
 =O_P(B^{-1/2}).                                               \tag{6}
\]
Both weak--strong products are \(O_P(B^{-1})=o_P(B^{-1/2})\), the multiplier expression in Assumption~\(\mathrm{ass{:}postselection\text{-}multiplier\text{-}condition}\) is \(O_P(B^{-1/2})=o_P(1)\), and
\[
 \max_{d\in\mathcal D}\max\bigl\{
 |\widehat V_{E,d}-V_{E,d}|,
 |\widehat V_{O,d}-V_{O,d}|\bigr\}=O_P(m^{-1/2}),
 \qquad
 \max\bigl\{
 |\widetilde V_{E,\widehat d_m,B}-V_{E,\widehat d_m}|,
 |\widetilde V_{O,\widehat d_m,B}-V_{O,\widehat d_m}|\bigr\}
 =O_P(B^{-1/2}).                                               \tag{7}
\]
Consequently the observational-norm weak-outcome and strong-selection conditions, the retained artificial-law strong-outcome and weak-selection conditions, and all product, multiplier, pilot-variance, and main-study-variance conditions used by Theorems~\(\mathrm{thm{:}pilot\text{-}oracle\text{-}regret}\) and \(\mathrm{thm{:}postselection\text{-}wald}\) are verified on this fixed-dimensional subclass, with \(r_{V,m}=m^{-1/2}\), \(r_{\widetilde V,B}=B^{-1/2}\), and all four bridge rates of order \(B^{-1/2}\).  Hence the oracle-regret, selected-design limit law, and Wald-coverage conclusions of those theorems hold without separately maintaining those rate conditions on this subclass.  No such conclusion is asserted for all of \(\mathfrak P_{\mathcal D}^{\mathrm{obs}}\).

statements.proof_tex:
We prove the proposed support-respecting statement.  All stochastic orders below are uniform because \(\mathcal D\), the treatment set, all basis dimensions, and the fold count are finite and fixed.

Fix \((d,a)\), and let \(n\) be the size of a relevant training source-arm sample.  The new sampling premise makes the observations within that source independent and identically distributed.  Bounded bases, \(E_P(|Y|^{4+\delta}\mid G=O)<\infty\), source-arm positivity, and the proportional-size condition therefore give, entry by entry,
\[
 \widehat M^h_{d,a}-M^h_{d,a}=O_P(n^{-1/2}),
 \qquad
 \widehat g^h_{d,a}-g^h_{d,a}=O_P(n^{-1/2}),                 \tag{8}
\]
by Chebyshev's inequality.  The same conclusion holds for \(\widehat M^q_{d,a}-M^q_{d,a}\) and \(\widehat g^q_{d,a}-g^q_{d,a}\).  The latter two estimates may use different sources, but mutual independence of the source samples and the union bound preserve the joint order.  A finite union bound makes (8) simultaneous over designs, arms, and folds.

On the event \(\|\widehat M^h_{d,a}-M^h_{d,a}\|_{\mathrm{op}}<c_0/2\),
\[
 \|\widehat M^h_{d,a}x\|
 \ge \|M^h_{d,a}x\|
      -\|\widehat M^h_{d,a}-M^h_{d,a}\|_{\mathrm{op}}\|x\|
 \ge \frac{c_0}{2}\|x\|.                                  \tag{9}
\]
Hence \(\widehat M^h_{d,a}\) is nonsingular and \(\|\widehat M^{h,-1}_{d,a}\|_{\mathrm{op}}\le2/c_0\); the same argument applies to \(\widehat M^q_{d,a}\).  These events hold jointly with probability tending to one.  On them, the exact population equations yield
\[
 \widehat\beta_{d,a}-\beta_{d,a}
 =\widehat M_{d,a}^{h,-1}
 \left\{(\widehat g^h_{d,a}-g^h_{d,a})
 -(\widehat M^h_{d,a}-M^h_{d,a})\beta_{d,a}\right\},       \tag{10}
\]
with the analogous identity for \(\widehat\gamma_{d,a}-\gamma_{d,a}\).  The population coefficient vectors are bounded uniformly over the finite collection: the population inverses have norm at most \(c_0^{-1}\), while the outcome and selection right-hand sides are bounded by the moment and basis envelopes.  Consequently,
\[
 \max_{d,a,\ell}\left\{
 \|\widehat\beta_{d,a}^{(-\ell)}-\beta_{d,a}\|
 +\|\widehat\gamma_{d,a}^{(-\ell)}-\gamma_{d,a}\|
 \right\}=O_P(n^{-1/2}).                                    \tag{11}
\]
The stipulated zero value on singular empirical matrices is asymptotically irrelevant.

Bounded bases turn (11) into the pointwise envelopes
\[
 |\widehat h_d-h_d|\le C\|\widehat\beta_d-\beta_d\|,
 \qquad
 |\widehat q_d-q_d|\le C\|\widehat\gamma_d-\gamma_d\|.    \tag{12}
\]
Taking \(n\asymp B\), the first envelope gives
\[
 \|\widehat h_{d,B}^{(-\ell)}-h_d\|_{2,B}^{\circ}
 =O_P(B^{-1/2}).                                               \tag{13}
\]
Conditional expectation is an \(L_2\)-contraction on the observational source, so
\[
 \|T_d(\widehat h_{d,B}^{(-\ell)}-h_d)\|_{2,O,q,d}
 \le \|\widehat h_{d,B}^{(-\ell)}-h_d\|_{2,O,h,d}
 =O_P(B^{-1/2}).                                               \tag{14}
\]
The second envelope directly gives
\[
 \|\widehat q_{d,B}^{(-\ell)}-q_d\|_{2,O,q,d}
 =O_P(B^{-1/2}).                                               \tag{15}
\]
Moreover, every source-defined version of \(T_d^\star(\widehat q_d-q_d)\) is bounded in absolute value by the right-hand envelope in (12), because conditional expectation preserves a pointwise bound.  Therefore
\[
 \|T_d^\star(\widehat q_{d,B}^{(-\ell)}-q_d)\|_{2,B}^{\circ}
 =O_P(B^{-1/2}).                                               \tag{16}
\]
Equations (13)--(16) prove (5)--(6), and either weak--strong product is \(O_P(B^{-1})=o_P(B^{-1/2})\).

Write \(\Delta h_{B,\ell}=\widehat h_{d,B}^{(-\ell)}-h_d\) and \(\Delta q_{B,\ell}=\widehat q_{d,B}^{(-\ell)}-q_d\).  The population bridges are bounded because their bases and coefficients are bounded.  Equations (11)--(12), the finite second moment of \(Y\), and Cauchy--Schwarz imply
\[
 \|\mathbf1\{G=O\}\Delta q_{B,\ell}(Y-h_d)\|_{2,B}^{\circ}
 +\|\mathbf1\{G=O\}q_d\Delta h_{B,\ell}\|_{2,B}^{\circ}
 =O_P(B^{-1/2}),                                               \tag{17}
\]
and
\[
 \|\mathbf1\{G=O\}\Delta q_{B,\ell}\Delta h_{B,\ell}\|_{2,B}^{\circ}
 =O_P(B^{-1}).                                                 \tag{18}
\]
Thus the multiplier expression is \(O_P(B^{-1/2})=o_P(1)\).

We next isolate the experimental centering coordinate omitted by the earlier argument.  For an experimental evaluation sample in arm \(a\), let \(P_{E,a}\) denote population arm-conditional expectation and \(\widehat P_{E,a}\) its empirical analogue.  For every fold-external outcome-bridge fit, the identity
\[
 \widehat\mu_{d,a}^{(-\ell)}-\mu_{d,a}
 =P_{E,a}(\widehat h_d^{(-\ell)}-h_d)
 +(\widehat P_{E,a}-P_{E,a})h_d
 +(\widehat P_{E,a}-P_{E,a})(\widehat h_d^{(-\ell)}-h_d)    \tag{19}
\]
is exact.  The first term is \(O_P(n^{-1/2})\) by (11) and bounded population basis means.  The second is \(O_P(n^{-1/2})\) by independent and identically distributed experimental sampling and boundedness of \(h_d\).  For the third term, write the fitted difference as the bounded basis multiplied by \(\widehat\beta_{d,a}^{(-\ell)}-\beta_{d,a}\).  The coefficient difference is \(O_P(n^{-1/2})\) by (11), and the empirical-minus-population basis mean is \(O_P(n^{-1/2})\).  The outcome-bridge fit is trained on observational data and is independent of the experimental evaluation sample, so their product is \(O_P(n^{-1})\).  Therefore, uniformly over the finite designs, arms, and folds,
\[
 \widehat\mu_{d,a}^{(-\ell)}-\mu_{d,a}=O_P(n^{-1/2}).        \tag{20}
\]
In particular, the load-bearing term \(P_{E,a}(\widehat h-h)\) has not been discarded.

The empirical arm probabilities obey \(\widehat p_{g,a}-p_{g,a}=O_P(n^{-1/2})\), and source-arm positivity makes their inverses stochastically bounded.  For one fold, the experimental score difference has the exact form
\[
\begin{aligned}
 \widehat\phi_{E,d}-\phi_{E,d}
 =\sum_{a=0}^1(-1)^{1-a}\mathbf1\{A=a\}\bigg[&
 \left(\widehat p_{E,a}^{-1}-p_{E,a}^{-1}\right)
 \{h_d(a)-\mu_{d,a}\}\\
 &+\widehat p_{E,a}^{-1}
 \{\Delta h_{d,a}-(\widehat\mu_{d,a}^{(-\ell)}-\mu_{d,a})\}
 \bigg],                                                     \tag{21}
\end{aligned}
\]
where the suppressed arguments agree with the theorem's score definition.  Equations (11)--(12) and (20), together with the arm-probability rate, imply
\[
 \|\widehat\phi_{E,d}-\phi_{E,d}\|_2=O_P(n^{-1/2}).         \tag{22}
\]
Thus the experimental score error is controlled jointly by coefficient error, arm-probability error, and the full three-term centering error.

For the observational score, direct subtraction gives terms proportional to the arm-probability error and to
\[
 \Delta q_d(Y-h_d)-q_d\Delta h_d-\Delta q_d\Delta h_d.       \tag{23}
\]
Boundedness of \(q_d,h_d\), (11)--(12), and \(E_P(Y^2\mid G=O)<\infty\) imply
\[
 \|\widehat\phi_{O,d}-\phi_{O,d}\|_2=O_P(n^{-1/2}).         \tag{24}
\]
The experimental population score is bounded, and the observational population score has a finite fourth moment because \(q_d,h_d\) are bounded and \(E_P(|Y|^{4+\delta}\mid G=O)<\infty\).

Let \(\mathbb P_n\) be an evaluation-source empirical measure.  For either source and any fixed design,
\[
\begin{aligned}
 |\mathbb P_n\widehat\phi_{g,d}^2-P\phi_{g,d}^2|
 \le{}&| (\mathbb P_n-P)\phi_{g,d}^2|\\
 &+\{\mathbb P_n(\widehat\phi_{g,d}-\phi_{g,d})^2\}^{1/2}
   \{\mathbb P_n(\widehat\phi_{g,d}+\phi_{g,d})^2\}^{1/2}. \tag{25}
\end{aligned}
\]
The first term is \(O_P(n^{-1/2})\) by Chebyshev's inequality applied to \(\phi_{g,d}^2\).  Equations (22)--(24), their bounded-basis envelopes, and the empirical second-moment bound for \(Y\) make the second term \(O_P(n^{-1/2})\), even though the empirical arm proportions and centering means are computed from the evaluation sample.  Fixed-fold averaging and a finite union bound preserve the rate.  With \(n\asymp m\) in the pilot and \(n\asymp B\) in the main study, (25) yields
\[
 \max_{d\in\mathcal D}\max\bigl\{
 |\widehat V_{E,d}-V_{E,d}|,
 |\widehat V_{O,d}-V_{O,d}|\bigr\}=O_P(m^{-1/2})             \tag{26}
\]
and, first uniformly in \(d\) and hence also at the pilot-selected random design,
\[
 \max_{g\in\{E,O\}}
 |\widetilde V_{g,\widehat d_m,B}-V_{g,\widehat d_m}|
 =O_P(B^{-1/2}).                                               \tag{27}
\]

Equations (13)--(18) and (26)--(27) verify all four bridge rates, both product conditions, the multiplier condition, and both variance-rate conditions with
\[
 r_{V,m}=m^{-1/2},\qquad r_{\widetilde V,B}=B^{-1/2}.
\]
They also verify the associated vanishing conditions.  The pilot is independent of the main study by the newly stated premise, and the two main-study sources have the independent and identically distributed sampling structure required by Theorem~\(\mathrm{thm{:}postselection\text{-}wald}\).  We may therefore apply Theorem~\(\mathrm{thm{:}pilot\text{-}oracle\text{-}regret}\) and Theorem~\(\mathrm{thm{:}postselection\text{-}wald}\), which give the asserted oracle regret, selected-design normal limit, and Wald coverage.  The argument depends on the fixed-dimensional basis, rank, moment, positivity, sampling, and fold-size conditions stated in the proposed theorem, so it does not extend these conclusions to all of \(\mathfrak P_{\mathcal D}^{\mathrm{obs}}\).

statements.statement:
First fix \(P\in\mathfrak P_{\mathcal D}^{\mathrm{CLW}}\) and \(B>0\). The named continuous CLW population rule has the exact finite-catalogue ratios
\[
 \rho_{\mathrm{CLW}}(P;B)
 =\frac{\min_{d\in\mathcal D_{\mathrm{CLW}}(P;B)}
 (\sqrt{c_{E,d}V_{E,d}}+\sqrt{c_{O,d}V_{O,d}})^2}
 {\min_{d'\in\mathcal D}
 (\sqrt{c_{E,d'}V_{E,d'}}+\sqrt{c_{O,d'}V_{O,d'}})^2}
 \in[1,\infty),                                            \tag{1}
\]
\[
 \rho_{\mathrm{CLW}}^{\mathrm{IKM}}(P;B)
 =\frac{\min_{d\in\mathcal D_{\mathrm{CLW}}(P;B)}
 \mathcal V_{d,\mathrm{IKM}}^*(P)}
 {\min_{d'\in\mathcal D}\mathcal V_{d',\mathrm{IKM}}^*(P)}
 \in[1,\infty).                                            \tag{2}
\]
Each ratio is the smallest constant for its actual best-tie selector. For either positive profile \(w_d\), the least constant making every named-rule order implication valid is
\[
 \max_{\substack{d,d'\in\mathcal D:\,
 \Psi_{\mathrm{CLW},d}(P;B)
 \le\Psi_{\mathrm{CLW},d'}(P;B)}}\frac{w_d}{w_{d'}}.       \tag{3}
\]
On the positive-count integer domain, the same formula with \(\Psi_{\mathrm{CLW}}^{\mathrm{int}}\) gives the exact integer-selector constant. Computing every criterion, selector, and pairwise maximum takes at most \(O(|\mathcal D|^2)\) arithmetic comparisons after the designwise moments have been supplied.

Separately, for every \(P\in\mathfrak P_{\mathcal D}^{\mathrm{obs}}\), the generic unrestricted unadjusted and treatment-aware population squared-risk rules have the exact identities
\[
 \rho_{\mathrm{pred}}(P)
 =\frac{\min_{d\in\mathcal D_{\mathrm{pred}}(P)}\mathcal V_d^*(P)}
 {\min_{d'\in\mathcal D}\mathcal V_{d'}^*(P)},
 \qquad
 \rho_{\mathrm{pred}}^A(P)
 =\frac{\min_{d\in\mathcal D_{\mathrm{pred}}^A(P)}\mathcal V_d^*(P)}
 {\min_{d'\in\mathcal D}\mathcal V_{d'}^*(P)},            \tag{4}
\]
with the analogous two IKM-normalized identities and the corresponding exact pairwise maxima ordered by \(R_d(P)\) or \(R_d^A(P)\). These generic assertions do not require \(P\in\mathfrak P_{\mathcal D}^{\mathrm{CLW}}\).

The jointly shrunk binary regions have unbounded best-tie ratios for the named CLW rule and, secondarily, for both generic rules under both profiles. At every center all six ratios agree and
\[
 \epsilon^2\inf_{\chi>1}\rho(P_{\chi,\epsilon})
 =\frac1{726}+\frac{5\sqrt[3]{12}}{968}\epsilon^{2/3}
 +o(\epsilon^{2/3}),                                       \tag{5}
\]
where \(\rho\) can be any of the six center ratios. Thus finiteness gives an exact computable lawwise enumeration, not a law-uniform named or generic guarantee.

Fix \(\chi>1\), let \(\epsilon_m\in(0,10^{-3})\) satisfy \(\epsilon_m\downarrow0\), and suppose the independently funded full-catalogue pilot consists of independent and identically distributed draws from \(P_{\chi,\epsilon_m}\), independently of the main study. Apply the split-sample saturated finite-cell rule in Definition~\(\mathrm{def{:}treatment\text{-}aware\text{-}pilot\text{-}selector}\). Then
\[
 \max_{d\in\mathcal D}
 |\widehat R_{d,m}^A-R_d^A(P_{\chi,\epsilon_m})|=O_P(m^{-1/2}), \tag{1}
\]
\[
 P_{\chi,\epsilon_m}\{\widehat d_m^A=d_{\mathrm p}\}\longrightarrow1. \tag{2}
\]
Moreover, the achieved arm-normalized and IKM-normalized profile ratios diverge in probability:
\[
 \frac{\mathcal V_{\widehat d_m^A}^*(P_{\chi,\epsilon_m})}
 {\min_{d\in\mathcal D}\mathcal V_d^*(P_{\chi,\epsilon_m})}
 \longrightarrow_P\infty,
 \qquad
 \frac{\mathcal V_{\widehat d_m^A,\mathrm{IKM}}^*(P_{\chi,\epsilon_m})}
 {\min_{d\in\mathcal D}\mathcal V_{d,\mathrm{IKM}}^*(P_{\chi,\epsilon_m})}
 \longrightarrow_P\infty. \tag{3}
\]
Thus the treatment-aware population impossibility is attained by a feasible pilot selector using only bounded binary outcomes and saturated finite-cell regression; no inverse-problem learner or growing sieve is used.

Fix \(\chi>1\).  For every \(0<\epsilon<10^{-3}\) and every \(B\ge5\chi\), the exact integer-budget CLW selector at \(P_{\chi,\epsilon}\) is \(\{d_{\mathrm p}\}\), whereas \(D^*(P_{\chi,\epsilon})=D_{\mathrm{IKM}}^*(P_{\chi,\epsilon})=\{d_{\mathrm e}\}\).  The eight center ratios
\[
 \rho_{\mathrm{CLW}},\quad
 \rho_{\mathrm{CLW}}^{\mathrm{int}},\quad
 \rho_{\mathrm{pred}},\quad
 \rho_{\mathrm{pred}}^A,
 \qquad
 \rho_{\mathrm{CLW}}^{\mathrm{IKM}},\quad
 \rho_{\mathrm{CLW}}^{\mathrm{IKM,int}},\quad
 \rho_{\mathrm{pred}}^{\mathrm{IKM}},\quad
 \rho_{\mathrm{pred}}^{A,\mathrm{IKM}}
\]
all equal
\[
 \rho_\chi(\epsilon)=\frac{25}{3872}
 \left\{
 \sqrt{\frac{20\chi(5\chi-1)}{10\chi-3}}
 +\sqrt{\frac{32(5\chi+1)}{75(10\chi-3)}
 (\epsilon^{-2}+14)}
 \right\}^{2}.                                             \tag{1}
\]
This common value exceeds \((\epsilon^{-2}+14)/726\) and, for fixed \(\chi\),
\[
 \rho_\chi(\epsilon)=
 \frac{5\chi+1}{363(10\chi-3)}\epsilon^{-2}
 +O_\chi(\epsilon^{-1}).                                  \tag{2}
\]
For every \(B\ge5\chi\), the suitably shrunk regions satisfy
\[
 \sup_{P\in\mathcal U_{\mathrm{bin}}}
 \rho_{\mathrm{CLW}}^{\mathrm{int}}(P;B)=\infty,
 \qquad
 \sup_{P\in\mathcal U_{\mathrm{bin}}^{\mathrm{IKM}}}
 \rho_{\mathrm{CLW}}^{\mathrm{IKM,int}}(P;B)=\infty.      \tag{3}
\]
The optimized integer envelope is understood with joint budget feasibility:
\[
 \inf_{\substack{\chi>1\\ B\ge5\chi}}
 \rho_{\mathrm{CLW}}^{\mathrm{int}}(P_{\chi,\epsilon};B)
 =\inf_{\substack{\chi>1\\ B\ge5\chi}}
 \rho_{\mathrm{CLW}}^{\mathrm{IKM,int}}(P_{\chi,\epsilon};B)
 =\inf_{\chi>1}\rho_\chi(\epsilon),                     \tag{4}
\]
and every minimizing \(\chi\) satisfies
\[
 \chi_{\mathrm{opt}}(\epsilon)
 \sim\frac{\sqrt[3]{18}}{15}\epsilon^{-2/3},
\]
\[
 \epsilon^2\inf_{\chi>1}\rho_\chi(\epsilon)
 =\frac1{726}+\frac{5\sqrt[3]{12}}{968}\epsilon^{2/3}
 +o(\epsilon^{2/3}).                                      \tag{5}
\]
Thus (5) applies along any budget schedule large enough to satisfy \(B_\epsilon\ge5\chi_{\mathrm{opt}}(\epsilon)\); it is not an unrestricted optimization over \(\chi\) at one fixed finite budget.  The named empirical counterpart is treated separately and no result concerns approximate OGA, an arbitrary predictive method, the original randomized-trial theorem, persistent-confounding analysis by Carneiro--Lee--Wilhelm, or bridge-role choice by that paper.

Fix \(\chi>1\), let \(\epsilon_m\in(0,10^{-3})\) satisfy \(\epsilon_m\downarrow0\), and suppose the independently funded full-catalogue pilot consists of independent and identically distributed draws from \(P_{\chi,\epsilon_m}\), independently of the main study.  Apply Definition~\(\mathrm{def{:}clw\text{-}empirical\text{-}linear\text{-}cost\text{-}selector}\).  Then
\[
 \max_{d\in\mathcal D}
 \left|\widehat r_{d,m}^{\mathrm{lin}}
 -r_d^{\mathrm{lin}}(P_{\chi,\epsilon_m})\right|
 =O_P(m^{-1/2}).                                           \tag{1}
\]
For every fixed \(B\ge5\chi\),
\[
 \max_{d\in\mathcal D}
 \left|\widehat\Psi_{\mathrm{CLW},d,m}^{\mathrm{int}}(B)
 -\Psi_{\mathrm{CLW},d}^{\mathrm{int}}(P_{\chi,\epsilon_m};B)\right|
 =O_P(m^{-1/2}),                                           \tag{2}
\]
with the analogous conclusion for the continuous criteria, and
\[
 P_{\chi,\epsilon_m}\!\left\{
 \widehat d_{\mathrm{CLW},m}(B)
 =\widehat d_{\mathrm{CLW},m}^{\mathrm{int}}(B)
 =d_{\mathrm p}\right\}\longrightarrow1.                \tag{3}
\]
Moreover,
\[
 \widehat\rho_{\mathrm{CLW},m}^{\mathrm{int}}
 (P_{\chi,\epsilon_m};B)\longrightarrow_P+\infty,
 \qquad
 \widehat\rho_{\mathrm{CLW},m}^{\mathrm{IKM,int}}
 (P_{\chi,\epsilon_m};B)\longrightarrow_P+\infty.       \tag{4}
\]
No rate relation between \(m\) and \(\epsilon_m\) is required.  The boundary \(B=5\chi\) is included.  No conclusion is asserted for \(B<5\chi\), where the prediction-selected design can have zero exact budget count, or at the singular limit \(\epsilon=0\).  This theorem analyzes the exact finite-catalogue affine least-squares minimizer corresponding to Carneiro--Lee--Wilhelm equation~(3.6), not their approximate OGA procedure.
